```sparql
PREFIX lad: <https://example.org/ladder/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?e ?name ?label ?country ?type ?lei ?parent ?src WHERE {
  ?e a lad:Entity .
  OPTIONAL {?e lad:name ?name}
  OPTIONAL {?e rdfs:label ?label}
  OPTIONAL {?e lad:country ?country}
  OPTIONAL {?e lad:entityType ?type}
  OPTIONAL {?e lad:lei ?lei}
  OPTIONAL {?e lad:parent ?parent}
  OPTIONAL {?e lad:sourceSystem ?src}
} ORDER BY ?e
```

