```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT ?lei (GROUP_CONCAT(CONCAT(STR(?e),":",?c,":",?s);separator=" | ") AS ?recs) WHERE {
 ?e lad:lei ?lei; lad:country ?c; lad:sourceSystem ?s .
 FILTER EXISTS { ?e2 lad:lei ?lei . FILTER(?e2!=?e) }
} GROUP BY ?lei ORDER BY ?lei
```

```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT (COUNT(DISTINCT ?k) AS ?n) (COUNT(DISTINCT ?q) AS ?qa) WHERE {
 { ?e a lad:Entity; lad:sourceSystem ?s . FILTER(?s!="QA") OPTIONAL{?e lad:lei ?l} BIND(COALESCE(?l,STR(?e)) AS ?k) }
 UNION { ?e a lad:Entity; lad:sourceSystem "QA" . BIND(?e AS ?q) }
}
```

```sparql
PREFIX lad: <https://example.org/ladder/>
